function gps = simulate_gps(truth, config)
%SIMULATE_GPS Generate virtual two-dimensional GPS measurements.
%
% Inputs:
%   truth  - Ground-truth structure generated by
%            generate_truth_trajectory.m
%
%   config - GPS configuration structure generated by
%            create_gps_config.m
%
% Output:
%   gps    - Structure containing:
%            GPS position measurements
%            measurement-noise samples
%            update masks
%            outage masks
%            measurement availability
%
% Measurement model:
%
%   z_gps(k) = position_true(k) + measurement_noise(k)
%
% A GPS measurement exists only when:
%
%   1. The sample corresponds to the configured GPS update rate.
%   2. The sample is not within a GPS outage.
%
% Samples without a GPS measurement are stored as NaN.

    %% Validate required truth fields

    required_truth_fields = { ...
        'time', ...
        'dt', ...
        'position_x', ...
        'position_y'};

    for field_index = 1:numel(required_truth_fields)

        current_field = required_truth_fields{field_index};

        if ~isfield(truth, current_field)
            error( ...
                'The truth structure does not contain "%s".', ...
                current_field);
        end
    end

    %% Validate configuration

    validateattributes( ...
        config.update_frequency, ...
        {'numeric'}, ...
        {'scalar', 'real', 'finite', 'positive'});

    validateattributes( ...
        config.position_noise_std_x, ...
        {'numeric'}, ...
        {'scalar', 'real', 'finite', 'nonnegative'});

    validateattributes( ...
        config.position_noise_std_y, ...
        {'numeric'}, ...
        {'scalar', 'real', 'finite', 'nonnegative'});

    %% Basic dimensions

    time = truth.time(:);
    dt = truth.dt;

    position_x_true = truth.position_x(:);
    position_y_true = truth.position_y(:);

    number_of_samples = numel(time);

    if numel(position_x_true) ~= number_of_samples || ...
            numel(position_y_true) ~= number_of_samples

        error( ...
            'Ground-truth position vectors must match the time vector.');
    end

    %% Calculate GPS sampling interval

    gps_period = 1 / config.update_frequency;

    samples_per_gps_update_exact = gps_period / dt;

    samples_per_gps_update = ...
        round(samples_per_gps_update_exact);

    sampling_compatibility_error = abs( ...
        samples_per_gps_update_exact ...
        - samples_per_gps_update);

    if sampling_compatibility_error > 1e-9
        error( ...
            ['The GPS update frequency is not compatible with the ' ...
             'simulation time step.']);
    end

    if samples_per_gps_update < 1
        error( ...
            'The GPS update rate cannot exceed the simulation rate.');
    end

    %% Create scheduled GPS-update mask

    scheduled_update_mask = ...
        false(number_of_samples, 1);

    scheduled_indices = ...
        1:samples_per_gps_update:number_of_samples;

    scheduled_update_mask(scheduled_indices) = true;

    %% Create GPS outage mask

    outage_mask = false(number_of_samples, 1);

    if isfield(config, 'outage_windows') && ...
            ~isempty(config.outage_windows)

        outage_windows = config.outage_windows;

        if size(outage_windows, 2) ~= 2
            error( ...
                'Each GPS outage window must contain a start and end time.');
        end

        for outage_index = 1:size(outage_windows, 1)

            outage_start = outage_windows(outage_index, 1);
            outage_end = outage_windows(outage_index, 2);

            if outage_end <= outage_start
                error( ...
                    'GPS outage end time must exceed its start time.');
            end

            current_outage_mask = ...
                time >= outage_start ...
                & time < outage_end;

            outage_mask = ...
                outage_mask | current_outage_mask;
        end
    end

    %% Determine available GPS measurements

    available_measurement_mask = ...
        scheduled_update_mask & ~outage_mask;

    valid_measurement_indices = ...
        find(available_measurement_mask);

    number_of_measurements = ...
        numel(valid_measurement_indices);

    %% Set random-number generator

    rng(config.random_seed, 'twister');

    %% Preallocate outputs using NaN for unavailable samples

    position_x_measured = ...
        nan(number_of_samples, 1);

    position_y_measured = ...
        nan(number_of_samples, 1);

    position_noise_x = ...
        nan(number_of_samples, 1);

    position_noise_y = ...
        nan(number_of_samples, 1);

    %% Generate GPS measurement noise

    valid_noise_x = ...
        config.position_noise_std_x ...
        * randn(number_of_measurements, 1);

    valid_noise_y = ...
        config.position_noise_std_y ...
        * randn(number_of_measurements, 1);

    position_noise_x(valid_measurement_indices) = ...
        valid_noise_x;

    position_noise_y(valid_measurement_indices) = ...
        valid_noise_y;

    %% Generate GPS position measurements

    position_x_measured(valid_measurement_indices) = ...
        position_x_true(valid_measurement_indices) ...
        + valid_noise_x;

    position_y_measured(valid_measurement_indices) = ...
        position_y_true(valid_measurement_indices) ...
        + valid_noise_y;

    %% Calculate measurement errors

    position_error_x = ...
        position_x_measured - position_x_true;

    position_error_y = ...
        position_y_measured - position_y_true;

    horizontal_position_error = hypot( ...
        position_error_x, ...
        position_error_y);

    %% Store outputs

    gps.time = time;
    gps.dt = dt;

    gps.update_frequency = ...
        config.update_frequency;

    gps.update_period = ...
        gps_period;

    gps.samples_per_update = ...
        samples_per_gps_update;

    gps.position_x_measured = ...
        position_x_measured;

    gps.position_y_measured = ...
        position_y_measured;

    gps.position_noise_x = ...
        position_noise_x;

    gps.position_noise_y = ...
        position_noise_y;

    gps.position_error_x = ...
        position_error_x;

    gps.position_error_y = ...
        position_error_y;

    gps.horizontal_position_error = ...
        horizontal_position_error;

    gps.scheduled_update_mask = ...
        scheduled_update_mask;

    gps.outage_mask = ...
        outage_mask;

    gps.available_measurement_mask = ...
        available_measurement_mask;

    gps.valid_measurement_indices = ...
        valid_measurement_indices;

    gps.number_of_scheduled_updates = ...
        nnz(scheduled_update_mask);

    gps.number_of_available_measurements = ...
        number_of_measurements;

    gps.number_of_suppressed_measurements = ...
        nnz(scheduled_update_mask & outage_mask);

    gps.config = config;
end